import{_ as t,o as e,c as r,a2 as c}from"./chunks/framework.BWuWLRhz.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/legacy/React系列/react中使用echarts就这么简单.md","filePath":"wiki/legacy/React系列/react中使用echarts就这么简单.md"}'),o={name:"wiki/legacy/React系列/react中使用echarts就这么简单.md"};function n(p,a,s,i,h,m){return e(),r("div",null,[...a[0]||(a[0]=[c(`<h3 id="我们真的需要react-echarts插件吗" tabindex="-1">我们真的需要react-echarts插件吗？ <a class="header-anchor" href="#我们真的需要react-echarts插件吗" aria-label="Permalink to &quot;我们真的需要react-echarts插件吗？&quot;">​</a></h3><h3 id="no" tabindex="-1">NO！！！ <a class="header-anchor" href="#no" aria-label="Permalink to &quot;NO！！！&quot;">​</a></h3><p><strong>在这里，我使用echarts提供的模块化加载方式，实现了几个react-echarts图表组件：<a href="http://setcamp.tech" target="_blank" rel="noreferrer">react-echarts图表在线渲染查看</a></strong></p><p>你可以打开控制台，观察每个图表组件的加载情况。</p><p>但是，如果你认为仅仅是模块导入echarts的tooltip、grid这些插件就完事了，那么我也用不着写这篇文章分享了，下面会讲到另外一种异步加载方式。</p><p>导入echarts，最烦人的是什么？配置option是其一，其二就是极其庞大的echarts！特别是管理后台使用到echarts的时候，如果需要同个页面展示数十种图表类型，你就该好好考虑性能问题了。</p><h3 id="插件版本号" tabindex="-1">插件版本号 <a class="header-anchor" href="#插件版本号" aria-label="Permalink to &quot;插件版本号&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  &amp;amp;quot;echarts&amp;amp;quot;: &amp;amp;quot;^3.6.2&amp;amp;quot;,</span></span>
<span class="line"><span>  &amp;amp;quot;react&amp;amp;quot;: &amp;amp;quot;^15.6.1&amp;amp;quot;,</span></span>
<span class="line"><span>  &amp;amp;quot;react-dom&amp;amp;quot;: &amp;amp;quot;^15.6.1&amp;amp;quot;</span></span></code></pre></div><h3 id="实现了哪些图表组件" tabindex="-1">实现了哪些图表组件 <a class="header-anchor" href="#实现了哪些图表组件" aria-label="Permalink to &quot;实现了哪些图表组件&quot;">​</a></h3><p>1、饼图 2、柱状图 3、折线图 4、散点图 5、地图 6、雷达图 7、k线图</p><h3 id="我们不总是需要插件" tabindex="-1">我们不总是需要插件 <a class="header-anchor" href="#我们不总是需要插件" aria-label="Permalink to &quot;我们不总是需要插件&quot;">​</a></h3><p>实现这些echarts-react组件的目的，是告诉大家，react可以不需要引入第三方插件，使用echarts，不要惧怕react组件！</p><p>看过很多人说react难写，因为他们习惯了在jQuery开发模式下导入echarts、swiper、d3等插件。而突然切换到react中，就产生了不知所措的感觉。 如何在react中导入第三方插件，成为了他们心中的痛点，所以一些人就认为需要别人封装好的echarts-react插件或者其他react插件，才能使用，这种想法是错的。</p><h3 id="echarts体积太大-使用模块化加载" tabindex="-1">echarts体积太大，使用模块化加载 <a class="header-anchor" href="#echarts体积太大-使用模块化加载" aria-label="Permalink to &quot;echarts体积太大，使用模块化加载&quot;">​</a></h3><p>以柱状图为例子，我们根据需要渲染的插件采取模块导入，不渲染的组件不导入，最大程度减小js。</p><pre><code>import echarts from &#39;echarts/lib/echarts&#39; //必须
import &#39;echarts/lib/component/tooltip&#39;
import &#39;echarts/lib/component/grid&#39;
import &#39;echarts/lib/chart/bar&#39;
</code></pre><h3 id="组件化开发的福音-react组件模块化加载" tabindex="-1">组件化开发的福音，react组件模块化加载 <a class="header-anchor" href="#组件化开发的福音-react组件模块化加载" aria-label="Permalink to &quot;组件化开发的福音，react组件模块化加载&quot;">​</a></h3><p>demo中采用单个echarts组件异步打包加载的模式，因为echarts组件普遍偏大，即使压缩也效果不明显，所以异步加载是最好的方式。</p><pre><code>import &amp;#123; pieOption, barOption, lineOption, scatterOption, mapOption, radarOption, candlestickOption &amp;#125; from &#39;./optionConfig/options&#39;
const PieReact = asyncComponent(() =&gt; import(/* webpackChunkName: &quot;PieReact&quot; */&#39;./EchartsDemo/PieReact&#39;))  //饼图组件
const BarReact = asyncComponent(() =&gt; import(/* webpackChunkName: &quot;BarReact&quot; */&#39;./EchartsDemo/BarReact&#39;)) //柱状图组件
const LineReact = asyncComponent(() =&gt; import(/* webpackChunkName: &quot;LineReact&quot; */&#39;./EchartsDemo/LineReact&#39;))  //折线图组件
const ScatterReact = asyncComponent(() =&gt; import(/* webpackChunkName: &quot;ScatterReact&quot; */&#39;./EchartsDemo/ScatterReact&#39;))  //散点图组件
const MapReact = asyncComponent(() =&gt; import(/* webpackChunkName: &quot;MapReact&quot; */&#39;./EchartsDemo/MapReact&#39;))  //地图组件
const RadarReact = asyncComponent(() =&gt; import(/* webpackChunkName: &quot;RadarReact&quot; */&#39;./EchartsDemo/RadarReact&#39;)) //雷达图组件
const CandlestickReact = asyncComponent(() =&gt; import(/* webpackChunkName: &quot;CandlestickReact&quot; */&#39;./EchartsDemo/CandlestickReact&#39;)) //k线图组件
</code></pre><h3 id="启动项目" tabindex="-1">启动项目 <a class="header-anchor" href="#启动项目" aria-label="Permalink to &quot;启动项目&quot;">​</a></h3><pre><code>//安装
npm install

//启动
npm start
</code></pre><h3 id="打包项目" tabindex="-1">打包项目 <a class="header-anchor" href="#打包项目" aria-label="Permalink to &quot;打包项目&quot;">​</a></h3><pre><code>npm run build
</code></pre><h3 id="实现方案介绍" tabindex="-1">实现方案介绍 <a class="header-anchor" href="#实现方案介绍" aria-label="Permalink to &quot;实现方案介绍&quot;">​</a></h3><p>1、每个图表单独封装成一个组件，通过参数传递数据，你会发现，图表内部代码几乎完全一样，只有import的类型不同。</p><p>2、异步加载是提高图表加载性能的最佳方式，不管是服务端还是客户端渲染。</p><p>3、在这些demo中，我认为对你来说最有价值的是react组件异步加载模式，很多人异步加载组件是通过拆分路由的方式，而非路由组件的异步加载，并不多人去尝试。但我想告诉你的是， 非路由组件的异步加载会将你的庞大的父组件拆分的更细，体积更小，加载的更加流畅。</p><p>===&gt; <a href="https://github.com/hyy1115/react-echarts-modules" target="_blank" rel="noreferrer">去往github查看react异步加载echarts源码</a></p>`,28)])])}const u=t(o,[["render",n]]);export{d as __pageData,u as default};
